test('Cancel aborts pending network work and immediate retry stays owned by the new attempt',async()=>{
 let attempts=0,firstSignal,release;
 const second=new Promise(resolve=>release=resolve),f=await fixture({enroll:init=>{if(++attempts===1){firstSignal=init.signal;return new Promise((_,reject)=>firstSignal.addEventListener('abort',()=>reject(new Error('Aborted fixture request')),{once:true}));}return second;}});
 f.element('connect-view').click();assert.equal(firstSignal.aborted,false);f.element('connection-cancel').click();assert.equal(firstSignal.aborted,true);
 f.element('connect-view').click();assert.equal(attempts,2);await new Promise(resolve=>setImmediate(resolve));assert.equal(f.dialog.querySelector('button[type="submit"]').disabled,true,'Old cancellation cleanup must not unlock an in-flight retry');assert.equal(f.element('connection-error').textContent,'');assert.equal(f.posted.filter(m=>m.type==='history').length,1);
 release({ok:true,status:200,json:async()=>({connected:true})});await until(()=>f.posted.filter(m=>m.type==='history').length===2);assert.equal(f.dialog.open,false);assert.equal(f.dialog.querySelector('button[type="submit"]').disabled,false);assert.equal(f.element('disconnect-view').hidden,false);assert.ok(!f.requests.some(route=>route.includes('disconnect')||route.includes('/cancel')));f.close();
});
